// Close a batch (PROBLEM-MELDEN-QA-TIERED-PROMPT.md, Tier 5).
//
//   node scripts/meldungen-schliessen.mjs docs/inhalte-qa/batch-<date>.json <commit> [--trocken]
//
// For every entry with an `entscheidung` ("erledigt" | "kein_fehler" | "doppelt"):
//   - its reports in public.meldungen get that status; "erledigt" also gets erledigt_commit = <commit>
//     (service role from .env.local)
//   - its findings in docs/inhalte-qa/befunde.json get status + commit too, so the next export
//     doesn't bring them back. (The script's own findings are regenerated by check-inhalte; a fixed
//     item simply stops producing one, an accepted "kein_fehler" stays closed by ref + check.)
// Entries without a decision are left alone. --trocken prints what would change.
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1")), "..");
const [batchArg, commit, ...rest] = process.argv.slice(2);
const DRY = rest.includes("--trocken");
const STATUS = new Set(["erledigt", "kein_fehler", "doppelt"]);
if (!batchArg || !commit || !/^[0-9a-f]{7,40}$/.test(commit)) {
  console.error("usage: node scripts/meldungen-schliessen.mjs <batch.json> <commit-hash> [--trocken]");
  process.exit(1);
}
const batch = JSON.parse(fs.readFileSync(path.resolve(ROOT, batchArg), "utf8"));
const decided = batch.eintraege.filter((e) => STATUS.has(e.entscheidung));

const env = (() => { try { return Object.fromEntries(fs.readFileSync(path.join(ROOT, ".env.local"), "utf8").split(/\r?\n/).filter((l) => /^[A-Z_]+=/.test(l)).map((l) => { const i = l.indexOf("="); return [l.slice(0, i), l.slice(i + 1).replace(/^["']|["']$/g, "")]; })); } catch { return {}; } })();
const URL_ = process.env.PUBLIC_SUPABASE_URL ?? env.PUBLIC_SUPABASE_URL;
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY ?? env.SUPABASE_SERVICE_ROLE_KEY;

let rows = 0;
for (const e of decided) {
  const ids = e.meldungen.map((m) => m.id);
  if (!ids.length) continue;
  const patch = { status: e.entscheidung, updated_at: new Date().toISOString(), ...(e.entscheidung === "erledigt" ? { erledigt_commit: commit } : {}), ...(e.notiz ? { notiz: e.notiz } : {}) };
  if (DRY) { console.log(`would set ${ids.length} report(s) on ${e.ref} → ${e.entscheidung}`); rows += ids.length; continue; }
  if (!URL_ || !KEY) { console.error("meldungen-schliessen: SUPABASE_SERVICE_ROLE_KEY missing (.env.local)."); process.exit(1); }
  const res = await fetch(`${URL_}/rest/v1/meldungen?id=in.(${ids.join(",")})`, {
    method: "PATCH",
    headers: { apikey: KEY, authorization: `Bearer ${KEY}`, "content-type": "application/json", prefer: "return=minimal" },
    body: JSON.stringify(patch),
  });
  if (!res.ok) { console.error(`meldungen-schliessen: ${e.ref}: Supabase ${res.status} ${await res.text()}`); process.exit(1); }
  rows += ids.length;
}

// Findings in befunde.json
const bPath = path.join(ROOT, "docs", "inhalte-qa", "befunde.json");
let befunde = [];
try { befunde = JSON.parse(fs.readFileSync(bPath, "utf8")); } catch {}
const decision = new Map(decided.map((e) => [e.ref, e.entscheidung]));
let closed = 0;
for (const b of befunde) {
  const d = decision.get(b.ref);
  if (!d || (b.status ?? "offen") !== "offen") continue;
  b.status = d;
  if (d === "erledigt") b.erledigt_commit = commit;
  closed++;
}
if (!DRY) fs.writeFileSync(bPath, JSON.stringify(befunde, null, 2) + "\n");
console.log(`meldungen-schliessen: ${decided.length} Einträge entschieden · ${rows} Meldung(en) in Supabase · ${closed} Befund(e) in befunde.json${DRY ? " (trocken, nichts geschrieben)" : ""}`);
